R,C=19,16
g=[[4]*C for _ in range(R)]
pts={ (2,2):1,(4,4):6,(4,14):1,(6,6):6,(7,14):6,(10,10):1,(15,2):6,(17,9):1}
for (r,c),v in pts.items(): g[r][c]=v
for r in range(2,11):
 c=r
 if g[r][c]==4:g[r][c]=1
for s in (8,12):
 for r in range(R):
  c=s-r
  if 0<=c<C and g[r][c]==4:g[r][c]=6
print('\n'.join(' '.join(map(str,row)) for row in g))
